use crate::commands::release_execution::execute_release;
use crate::commands::release_test_support::{envelope, evidence_for};
use crate::commands::{ReleasePreflight, ReleaseProviderSet};
use crate::error::{CommandFailure, RemoteConflict};
use crate::GraphError;

/// How many observations a landed effect stays invisible under injected
/// registry lag. Two is deliberate: one is absorbed by the post-effect
/// confirmation, so only a second exposes the rerun paths to a stale `Absent`.
const LAG_SPAN: usize = 2;

/// Reruns the operator is simulated as performing after a failed run. Runs 0
/// and 1 may still carry the scenario's faults, so runs 2 through 4 are the
/// three clean reruns convergence is asserted within.
const MAX_RERUNS: usize = 4;

/// The fault budget is spent inside the first two executions.
const FAULT_ARMED_RUNS: usize = 2;

// ---------------------------------------------------------------------------
// The intent under simulation
// ---------------------------------------------------------------------------

/// Two packages covering every operation role, wired with the production DAG
/// order: platform -> registry -> tag -> draft release -> every upload -> publication.
fn simulator_intent() -> (ReleaseIntentV1, ArtifactManifestV1) {
    let version = Version::semver(1, 2, 3);
    let registry = RegistryBindingId::new(
        "crates",
        RegistryBindingDigest::from_normalized_binding(b"crates-default"),
    )
    .unwrap();
    let alpha = ReleasePackageId::new(Ecosystem::Cargo, "alpha").unwrap();
    let beta = ReleasePackageId::new(Ecosystem::Cargo, "beta").unwrap();
    let repository = GitHubRepository::parse("orin-dx/callisto").unwrap();
    let workflow_commit = CommitSha::parse(&"b".repeat(40)).unwrap();
    let slot = |platform: &str, asset: &str| {
        ArtifactSlotId::new(
            alpha.clone(),
            version.clone(),
            platform,
            asset,
            repository.clone(),
            ".github/workflows/release.yml",
            workflow_commit.clone(),
        )
        .unwrap()
    };
    let linux = slot("x86_64-unknown-linux-gnu", "alpha-linux.tar.gz");
    let macos = slot("aarch64-apple-darwin", "alpha-macos.tar.gz");

    let alpha_registry =
        ReleaseOperation::registry_publish(alpha.clone(), version.clone(), registry.clone(), vec![]).unwrap();
    let alpha_tag = ReleaseOperation::tag(alpha.clone(), version.clone(), vec![alpha_registry.id().clone()]).unwrap();
    let alpha_draft =
        ReleaseOperation::forge_release(alpha.clone(), version.clone(), vec![alpha_tag.id().clone()]).unwrap();
    let linux_upload = ReleaseOperation::artifact_upload(linux.clone(), vec![alpha_draft.id().clone()]).unwrap();
    let macos_upload = ReleaseOperation::artifact_upload(macos.clone(), vec![alpha_draft.id().clone()]).unwrap();
    let alpha_publish = ReleaseOperation::forge_publish(
        alpha.clone(),
        version.clone(),
        vec![
            alpha_draft.id().clone(),
            linux_upload.id().clone(),
            macos_upload.id().clone(),
        ],
    )
    .unwrap();
    let beta_platform = ReleaseOperation::new(
        ReleaseOperationId::platform_publish(
            beta.clone(),
            version.clone(),
            registry.clone(),
            callisto_model::PlatformPackageV1::new(
                ReleasePackageId::new(Ecosystem::Npm, "beta-linux-x64-gnu").unwrap(),
                "beta/npm/linux-x64-gnu",
            )
            .unwrap(),
        ),
        vec![],
    )
    .unwrap();
    let beta_registry = ReleaseOperation::registry_publish(
        beta.clone(),
        version.clone(),
        registry,
        vec![beta_platform.id().clone()],
    )
    .unwrap();
    let beta_tag = ReleaseOperation::tag(beta.clone(), version.clone(), vec![beta_registry.id().clone()]).unwrap();

//! Release fixtures shared by this crate's unit tests.
//!
//! Every state needs a validated run envelope and every state change needs a
//! proof token, so the tests build both here rather than in each module.

use callisto_model::{
    ArtifactDigest, CommitSha, OperationEvent, ProviderEvidenceV1, ProviderObservationV1, ReleaseExecutionStateV1,
    ReleaseIntentV1, ReleaseOperationId, ReleaseOperationRole, ReleaseRunEnvelopeV1, TagName,
};

pub(crate) fn envelope(intent: &ReleaseIntentV1) -> ReleaseRunEnvelopeV1 {
    let orchestration = intent
        .artifact_slots
        .first()
        .map(|slot| slot.attestation_policy.workflow_commit.clone())
        .unwrap_or_else(|| CommitSha::parse(&"b".repeat(40)).unwrap());
    let manifest = (!intent.artifact_slots.is_empty()).then(|| ArtifactDigest::from_bytes(b"manifest"));
    ReleaseRunEnvelopeV1::new(orchestration, intent, manifest).expect("fixture envelope matches its intent")
}

pub(crate) fn pending_state(intent: &ReleaseIntentV1) -> ReleaseExecutionStateV1 {
    ReleaseExecutionStateV1::new(intent, envelope(intent)).expect("fixture state matches its intent")
}

/// Role-matching evidence, as a real provider adapter would report it.
pub(crate) fn evidence_for(id: &ReleaseOperationId) -> ProviderEvidenceV1 {
    match &id.role {
        ReleaseOperationRole::RegistryPublish { .. } | ReleaseOperationRole::PlatformPublish { .. } => {
            ProviderEvidenceV1::RegistryVersion {
                version: id.version.clone(),
                checksum: None,
                yanked: None,
            }
        }
        ReleaseOperationRole::Tag => ProviderEvidenceV1::GitTag {
            peeled_commit: CommitSha::parse(&"a".repeat(40)).unwrap(),
        },
        ReleaseOperationRole::ForgeRelease | ReleaseOperationRole::ForgePublish => ProviderEvidenceV1::ForgeRelease {
            tag_name: TagName::new_unchecked(format!("v{}", id.version.render())),
            draft: false,
        },
        ReleaseOperationRole::ArtifactUpload { .. } => ProviderEvidenceV1::ArtifactUpload {
            byte_length: 6,
            sha256: ArtifactDigest::from_bytes(b"binary"),
        },
    }
}

pub(crate) fn exact(id: &ReleaseOperationId) -> ProviderObservationV1 {
    ProviderObservationV1::Exact {
        evidence: evidence_for(id),
    }
}

pub(crate) fn attempt_event() -> OperationEvent {
    OperationEvent::Attempt {
        proof: ProviderObservationV1::Absent
            .absent_proof()
            .expect("absent mints a proof"),
    }
}

pub(crate) fn confirmed_event(id: &ReleaseOperationId) -> OperationEvent {
    OperationEvent::Confirmed {
        evidence: exact(id).exact_evidence().expect("exact mints evidence"),
    }
}

pub(crate) fn already_satisfied_event(id: &ReleaseOperationId) -> OperationEvent {
    OperationEvent::ObservedExactBeforeEffect {
        evidence: exact(id).exact_evidence().expect("exact mints evidence"),
    }
}

/// Drives one operation through the only legal path to `Published`.
pub(crate) fn publish_operation(state: &mut ReleaseExecutionStateV1, id: &ReleaseOperationId) {
    state.apply(id, &attempt_event()).unwrap();
    state.apply(id, &confirmed_event(id)).unwrap();
}

